import json
from pathlib import Path
from cryptography.hazmat.primitives.ciphers.aead import AESGCM

v = Path('/var/lib/vaultctl')
catalog = json.loads((v/'catalog.json').read_text())
keys = {p.stem: p.read_bytes() for p in sorted((v/'keys').glob('*.key'))}

print("key fingerprints (sha256[:12]):")
import hashlib
for name, k in keys.items():
    print(f"  {name:9s} len={len(k)} {hashlib.sha256(k).hexdigest()[:12]}")

for aid, meta in catalog.items():
    blob = (v/'archives'/(aid+'.bin')).read_bytes()
    nonce, ct = blob[:12], blob[12:]
    print(f"\narchive {aid} (catalog key_id={meta['key_id']}, {len(blob)} bytes)")
    ok = []
    for kname, k in keys.items():
        for aad in [meta['key_id'], kname, 'k-prev', 'k-next', 'k-unused']:
            try:
                pt = AESGCM(k).decrypt(nonce, ct, aad.encode())
                ok.append((kname, aad, pt))
            except Exception:
                pass
    if not ok:
        print("  !! NO key/AAD combination decrypts this archive")
    seen = set()
    for kname, aad, pt in ok:
        if (kname, aad) in seen: continue
        seen.add((kname, aad))
        print(f"  OK key={kname} aad={aad!r} -> {pt[:80]!r}")
EOF"}

